content.text:
                if absorbing and k == m:
                    for a in range(sigma):
                        table[a][m] = m
                    continue
                base = psym[:k]
                for a in range(sigma):
                    word = base + [a]
                    top = m if m < k + 1 else k + 1
                    j = top
                    while j > 0:
                        off = k + 1 - j
                        ok = True
                        for i in range(j):
                            if psym[i] != word[off + i]:
                                ok = False
                                break
                        if ok:
                            break
                        j -= 1
                    table[a][k] = j
        tables.append(table)
        true_states.append(true)
        widths.append(width)
    return tables, true_states, widths


def product_bfs(count, coltabs, sigma, cap):
    """Reachable synchronous product; raises ComplexErr above `cap` tuples."""
    init = (0,) * count
    index = {init: 0}
    states = [init]
    trans = []
    head = 0
    full = False
    while head < len(states):
        tup = states[head]
        head += 1
        row = [0] * sigma
        for a in range(sigma):
            nxt = tuple(map(getitem, coltabs[a], tup))
            ident = index.get(nxt)
            if ident is None:
                if full:
                    raise ComplexErr()
                ident = len(states)
                index[nxt] = ident
                states.append(nxt)
                if len(index) >= cap:
                    full = True
            row[a] = ident
        trans.append(row)
    return states, trans


# --------------------------------------------------------------------------
# boolean combination, evaluated as a bitset over all atom truth assignments
# --------------------------------------------------------------------------
def expr_mask(tree, var_masks, everything):
    kind = tree[0]
    if kind == 'c':
        return everything if tree[1] else 0
    if kind == 'a':
        return var_masks[tree[1]]
    if kind == 'n':
        return everything ^ expr_mask(tree[1], var_masks, everything)
    if kind == '&':
        result = everything
        for sub in tree[1]:
            result &= expr_mask(sub, var_masks, everything)
            if not result:
                break
        return result
    result = 0
    for sub in tree[1]:
        result |= expr_mask(sub, var_masks, everything)
        if result == everything:
            break
    return result


# --------------------------------------------------------------------------
# minimisation
# --------------------------------------------------------------------------
def seed_partition(n, sigma, trans, accept):
    """Initial refinement: states are separated by their distance to the
    nearest accepting state.  States at different distances can never be
    equivalent, so this is a safe refinement of the accept partition and it
    saves many refinement rounds."""
    if sigma:
        reverse = [[] for _ in range(n)]
        for q in range(n):
            for target in trans[q]:
                if target != q:
                    reverse[target].append(q)
    else:
        reverse = [[] for _ in range(n)]
    dist = [-1] * n
    queue = deque()
    for q in range(n):
        if accept[q]:
            dist[q] = 0
            queue.append(q)
    while queue:
        state = queue.popleft()
        step = dist[state] + 1
        for prev in reverse[state]:
            if dist[prev] < 0:
                dist[prev] = step
                queue.append(prev)
    numbering = {}
    part = [0] * n
    for q in range(n):
        value = dist[q]
        ident = numbering.get(value)
        if ident is None:
            ident = len(numbering)
            numbering[value] = ident
        part[q] = ident
    return part, len(numbering)


def moore(n, trans, part, blocks):
    """Round based refinement; returns (part, blocks, converged)."""
    for _ in range(MOORE_ROUNDS):
        getter = part.__getitem__
        marks = {}
        newpart = [0] * n
        count = 0
        for q in range(n):
            sig = (part[q],) + tuple(map(getter, trans[q]))
            ident = marks.get(sig)
            if ident is None:
                ident = count
                count += 1
                marks[sig] = ident
            newpart[q] = ident
        if count == blocks or count == n:
            return newpart, count, True
        part = newpart
        blocks = count
    return part, blocks, False
